"""Build the seven Module 1 pages without changing other modules."""
from pathlib import Path
from html import escape
import json,re
from module1_content import SECTIONS,FORMULAS,TRY_SOLUTIONS,REVIEW_SOLUTIONS,figure
ROOT=Path(__file__).resolve().parents[1]
CONTRACT=json.loads((ROOT/'scripts/module1_original_contracts.json').read_text())
NAV=[('Reading','readings/module01_reading.html'),('Unit circle','demos/unit_circle.html'),('Circle to wave','demos/circle_to_wave.html'),('Practice','practice/unit_circle_practice.html'),('Lab','labs/week01_lab.html'),('Applications','applications/week01_applications.html'),('Quiz','quizzes/week01_quiz.html')]
def page(path,title,body,kind='',config=None):
    nav=''.join(f'<a href="../{url}"'+(' aria-current="page"' if path==url else '')+f'>{label}</a>' for label,url in NAV)
    data=f'<script id="activityData" type="application/json">{json.dumps(config,ensure_ascii=False).replace("<",chr(92)+"u003c")}</script>' if config else ''
    content='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'''+f'<title>{escape(title)} | MATH&amp; 142</title><link rel="stylesheet" href="../assets/module1/module1.css">'+r'''
<script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},svg:{fontCache:'none'},options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']}};</script>
<script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js"></script>
<script defer src="../assets/module1/module1.js"></script></head>'''+f'<body data-page="{kind}"><a class="skip" href="#main">Skip to content</a><header class="masthead"><div><a href="../index.html">← Precalculus II</a><p class="eyebrow">MATH&amp; 142 · Module 1 · Dr. Lee</p><h1>{escape(title)}</h1><nav aria-label="Module 1">{nav}</nav></div></header><main id="main">{body}</main><footer><a href="../pdfs/PrecalcII_Week01.pdf">Module 1 PDF</a> · <a href="../pdfs/PrecalculusII_Complete_Reader.pdf">Complete course reader</a> · <a href="../index.html">Course home</a></footer>{data}</body></html>'
    target=ROOT/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
def tex_html(s):
    # These preserved prompts use only inline dollar math and plain paragraphs.
    parts=re.split(r'(\$[^$]*\$)',s.strip())
    return ''.join('\\('+p[1:-1]+'\\)' if p.startswith('$') else escape(re.sub(r'\s+',' ',p)) for p in parts)
def reading():
    b=r'''<section class="panel intro"><p>A turning wheel connects several ideas: angle, distance, speed, and position. This reading develops those connections from a coordinate sketch to a model of a rider’s height over time.</p><p>Work through the examples with pencil and paper. Pause at each “Check your understanding” before opening its explanation. You will use these ideas in the explorers, lab, and applications.</p><p><a class="button" href="../pdfs/PrecalcII_Week01.pdf">Download the reading (PDF)</a></p><h2>What you will learn</h2><ul><li>Describe signed rotations and convert between degrees and radians.</li><li>Distinguish arc length, displacement, angular velocity, and tangential speed.</li><li>Derive exact sine and cosine values and use them in every quadrant.</li><li>Connect circular motion with periodic graphs and a height model.</li></ul></section><nav class="toc panel" aria-label="Reading contents"><h2>In this reading</h2><ol>'''
    b+=''.join(f'<li><a href="#{s["id"]}">{s["title"]}</a></li>' for s in SECTIONS)+'</ol></nav>'
    for n,s in enumerate(SECTIONS,1):
        b+=f'<section class="panel reading-section" id="{s["id"]}"><p class="eyebrow">{n:02d}</p><h2>{s["title"]}</h2>{s["body"]}<div class="try"><h3>Check your understanding</h3><p>{s["question"]}</p><details><summary>Read the explanation</summary><p>{s["answer"]}</p></details></div></section>'
    b+='<section class="panel" id="formula-guide"><h2>Choose a relationship</h2><p>Start with what the situation asks. A formula becomes useful when its quantities and units match the question.</p>'+FORMULAS+'</section>'
    for title,key,answers in [('Practice with explanation','tryIts',TRY_SOLUTIONS),('Review exercises','exercises',REVIEW_SOLUTIONS)]:
        b+=f'<section class="panel"><h2>{title}</h2><p>Attempt each problem before opening the explanation.</p><ol class="problem-list">'
        for q,a in zip(CONTRACT[key],answers):b+=f'<li><p>{tex_html(q)}</p><details><summary>Solution and reasoning</summary><p>{a}</p></details></li>'
        b+='</ol></section>'
    b+='<section class="panel"><h2>Continue with the module</h2><p>Use the unit-circle explorer to test signed turns and radius changes. Then use Circle to Wave to follow a coordinate through two revolutions. Keep your sketches and units in your lab explanations.</p><p>Further reading: OpenStax, <em>Precalculus 2e</em>, <a href="https://openstax.org/books/precalculus-2e/pages/5-1-angles">5.1 Angles</a> and <a href="https://openstax.org/books/precalculus-2e/pages/5-2-unit-circle-sine-and-cosine-functions">5.2 Unit Circle: Sine and Cosine Functions</a>.</p></section>'
    page('readings/module01_reading.html','Angles, Radians, and the Unit Circle',b,'reading')
def angle_entries(prefix=''):
    return f'<div class="entry-pair"><label for="degreesEntry">Angle in degrees<input id="degreesEntry" type="text" inputmode="decimal" value="30" aria-describedby="{prefix}Error"></label><label for="radiansEntry">Angle in radians<input id="radiansEntry" type="text" value="pi/6" aria-describedby="{prefix}Error"></label></div><p class="small">Radians accept entries such as <code>pi/3</code>, <code>-3pi/4</code>, or <code>1.5</code>. Press Enter or move out of the field to apply.</p><p id="{prefix}Error" role="status" class="error"></p>'
def demos():
    b='<section class="panel"><p>Start at the rightmost point and turn. Compare the physical point on the adjustable circle with the normalized point on the unit circle. Sine and cosine depend on the angle; the physical coordinates also depend on the radius.</p></section><div class="explorer"><section class="panel controls"><h2>Set the rotation</h2><label for="angle">Angle slider: −720° to 720°<input id="angle" type="range" min="-720" max="720" step="any" value="30"></label>'+angle_entries('circle')+r'''<label for="radius">Physical radius <output id="rv">1</output><input id="radius" type="range" min="0.5" max="3" step="0.1" value="1"></label><div class="button-row"><button data-angle="45">45°</button><button data-angle="405">405°</button><button data-angle="-315">−315°</button><button id="reset">Reset</button></div><p class="small">The slider covers two turns in either direction. Typed entries may go beyond that range. An invalid entry clears the display until corrected.</p><h3>Try and explain</h3><ol><li>Compare 45°, 405°, and −315°. Which values match? Which record different journeys?</li><li>At 60°, change the radius from 1 to 3. Compare physical coordinates with sine and cosine.</li><li>At a negative angle, compare directed arc length with distance traveled.</li></ol></section><section class="panel plot-panel"><h2>Position on two circles</h2><div id="plot" class="circle-pair" aria-describedby="circleDescription"></div><p id="circleDescription" role="status"></p><div class="readouts"><p>Rotation: <strong id="deg"></strong> = <strong id="rad"></strong></p><p>One-turn representative: <strong id="terminalAngle"></strong></p><p>Physical point: <strong id="scaledXY"></strong></p><p>Unit-circle point: <strong id="xy"></strong></p><p>Cosine: <strong id="cosValue"></strong> · Sine: <strong id="sinValue"></strong></p><p>Reference angle: <strong id="ref"></strong></p><p>Directed arc: <strong id="arc"></strong></p><p>Distance along rim: <strong id="distance"></strong></p></div><p class="small">All lengths use the same arbitrary length unit. Distance assumes one continuous turn without reversing. The small angle arc shows the final direction; the readouts retain all full turns.</p></section></div>'''
    page('demos/unit_circle.html','Unit Circle Explorer',b,'circle')
    b=r'''<section class="panel"><p>Follow one rotating point. The green graph records its vertical coordinate, sine. The blue graph records its horizontal coordinate, cosine. Here the graph’s horizontal axis measures <strong>angle</strong>, not elapsed time.</p></section><div class="explorer"><section class="panel controls"><h2>Follow a turn</h2><label for="angle">Angle slider: 0° to 720°<input id="angle" type="range" min="0" max="720" step="any" value="30"></label>'''+angle_entries('wave')+r'''<label for="plotUnits">Graph angle units<select id="plotUnits"><option value="rad">Radians</option><option value="deg">Degrees</option></select></label><div class="button-row"><button data-quarter="0">0°</button><button data-quarter="90">90°</button><button data-quarter="180">180°</button><button data-quarter="270">270°</button><button data-quarter="360">360°</button><button data-quarter="720">720°</button></div><label for="speed">Playback speed<input id="speed" type="range" min="1" max="6" value="2"></label><div class="button-row"><button id="toggle">Play</button><button id="restart">Restart</button></div><p id="state" role="status">Paused</p><p class="small">Playback speed changes how fast the point moves on screen. The angle-based graphs keep the same shape.</p><h3>Pause and compare</h3><ol><li>At 90°, where is the circle point? Where is the sine value?</li><li>At 180°, sine is zero. What is cosine?</li><li>At 360° and 720°, what has repeated?</li></ol></section><section class="panel plot-panel"><h2>From coordinates to graphs</h2><div id="canvas" class="wave-plot"></div><p id="out" role="status"></p><div id="waveTable"></div><p class="small">Faint curves show two full cycles. Bold curves show the portion reached so far. For a graph against time, first specify the angular velocity and use \(\theta=\omega t\).</p></section></div>'''
    page('demos/circle_to_wave.html','Circle to Wave',b,'wave')
def fields(questions,scaffolds):
    b='<section class="panel"><div class="identity"><label for="student">Student name<input id="student" autocomplete="name" type="text"></label><label for="date">Date<input id="date" type="date"></label></div><p class="small" id="saveStatus" role="status">Your responses are saved on this device as you type. Prepare a submission copy to upload to Canvas, or print a PDF.</p></section><div id="questions">'
    for i,((title,q),guide) in enumerate(zip(questions,scaffolds)):
        b+=f'<section class="panel"><h2>{title}</h2><p>{escape(q)}</p><aside class="note small"><p>{guide}</p></aside><label for="a{i}">Your calculations and explanation</label><textarea id="a{i}" rows="6"></textarea></section>'
    return b+'</div><section class="panel"><h2>Before you submit</h2><p>Answer every question. Label units, explain what the numbers mean, and check your conclusions against a sketch. Add your name before creating your submission.</p><div class="button-row"><button id="prepare">Prepare submission (HTML)</button><button id="print">Print / Save PDF</button><button id="clear">Clear answers</button></div><p id="message" role="status"></p></section>'
def activities():
    guides=[r'Use a sketch to check the signs. Record both the angle and the ordered pair; coordinates are not angle measures.',r'Begin with \(\theta=s/r\). Convert the result using \(180^\circ/\pi\). Keep the exact ratio until the final rounding.',r'Compare each angle with 45° using additions or subtractions of 360°. Distinguish final position from total rotation.',r'The explorer displays physical coordinates and unit-circle coordinates separately. Explain which quantities scale with radius.',r'Follow the green coordinate. On the graph, angle is the input and vertical coordinate is the output.',r'Find the unit-circle vertical coordinate first, then scale by the radius. The question asks for displacement from the center, not height above ground.',r'Connect a half-circumference with the radius. Explain the ratio in words as well as symbols.']
    b='<section class="panel"><p>Investigate how turning becomes coordinates. Use the <a href="../demos/unit_circle.html" target="_blank" rel="noopener">Unit Circle Explorer</a> and <a href="../demos/circle_to_wave.html" target="_blank" rel="noopener">Circle to Wave</a>. Work through all seven questions; use observations to explain your reasoning.</p></section>'+fields(CONTRACT['lab'],guides)
    page('labs/week01_lab.html','Lab: Rotation into Coordinates',b,'written',{'kind':'written','key':CONTRACT['labKey'],'title':'Module 1 Lab','questions':CONTRACT['lab']})
    appq=CONTRACT['applications'];groups=[('1. Ferris wheel: where is the rider?',r'<p>A Ferris wheel has radius 12 m, with its center 14 m above the ground. A rider begins at the rightmost point, level with the center. The wheel rotates counterclockwise at a constant rate and takes 48 seconds per revolution.</p><p>For rotation \(\theta\) in radians, the rider’s height is \(h=14+12\sin\theta\) meters.</p>'+figure('application-ferris-setup','A Ferris wheel of radius 12 meters has center height 14 meters and a rider starting at the rightmost point.','Mark the start, center, and radius before calculating.'),4),('2. A rotating antenna: angular speed and distance',r'<p>An instrument platform turns at 4 revolutions per minute. A sensor sits 0.75 m from the rotation axis. Find how far it travels along its circular path over 15 seconds, and compare that with its displacement.</p>'+figure('application-antenna-setup','A sensor 0.75 meters from a rotation axis is tracked on a circular path at four revolutions per minute.','Keep track of both time units and angle units.'),4),('3. A wheel encodes a wave',r'<p>A recorder copies <em>only the vertical position</em> of a point on a rotating disk to a pen constrained to move up and down in a vertical guide. Paper moves past the guide at a steady speed, so horizontal distance on the paper represents elapsed time.</p><p>At a constant rotation rate, the recorded height rises and falls like sine. Use <a href="../demos/circle_to_wave.html">Circle to Wave</a> to follow the coordinate; its horizontal axis is angle, which can be converted to time once the rate is known.</p>',3)]
    b='<section class="panel"><p>For each situation, identify the quantities, choose a relationship, calculate, and explain whether the result makes sense. Answer all eleven questions.</p></section><section class="panel"><div class="identity"><label for="student">Student name<input id="student" type="text" autocomplete="name"></label><label for="date">Date<input id="date" type="date"></label></div><p id="saveStatus" role="status" class="small">Your responses are saved on this device as you type.</p></section>'
    questions=[];i=0
    for title,intro,count in groups:
        b+=f'<section class="panel"><h2>{title}</h2>{intro}<ol>'
        for j in range(count):
            q=appq[i];questions.append([f'{title} — question {j+1}',q]);b+=f'<li><p>{escape(q)}</p><label for="a{i}">Your work and explanation</label><textarea id="a{i}" rows="5"></textarea></li>';i+=1
        b+='</ol></section>'
    b+='<section class="panel"><h2>Check your models</h2><p>Use radians in arc-length formulas. Check the model at the starting time and after one full turn. Explain distance and displacement separately.</p><div class="button-row"><button id="prepare">Prepare submission (HTML)</button><button id="print">Print / Save PDF</button><button id="clear">Clear answers</button></div><p id="message" role="status"></p></section>'
    page('applications/week01_applications.html','Applications: Rotation in the World',b,'written',{'kind':'written','key':'m142app1','title':'Module 1 Applications','questions':questions})
def quiz():
    b='<section class="panel"><p>Work each problem before checking it. You can revise an answer after reading the hint. Correct responses remain mastered on this device.</p><p>Enter numbers without units in the answer fields. Exact entries such as <code>5pi/6</code>, <code>-sqrt(2)/2</code>, and <code>1/2</code> work. You may also use decimals rounded to three places. Keep units in your written work.</p><p id="score" class="note" role="status"></p></section><div id="questions">'
    for i,(q,a,h) in enumerate(CONTRACT['quiz']):b+=f'<section class="panel" data-quiz-index="{i}"><h2>Question {i+1}</h2><p>{escape(q)}</p><label for="q{i}">Answer</label><input type="text" id="q{i}" autocomplete="off" aria-describedby="feedback{i}"><button data-check-quiz="{i}">Check answer</button><p id="feedback{i}" role="status"></p><details><summary>Hint</summary><p>{escape(h)}</p></details></section>'
    b+='</div><section class="panel"><button id="reset">Reset quiz mastery</button><p class="small">This feedback is stored in your browser. It is not automatically submitted to Canvas.</p></section>'
    page('quizzes/week01_quiz.html','Module 1 Quiz',b,'quiz',{'kind':'quiz','key':CONTRACT['quizKey'],'questions':CONTRACT['quiz']})
def practice():
    b=r'''<section class="panel"><p>Use the reference angle and quadrant to reason through each answer. For conversions, start with \(180^\circ=\pi\) radians. After you answer correctly, the circle reveals the angle and the explanation connects it with the coordinates.</p><div class="identity"><label for="topic">Practice topic<select id="topic"><option value="mix">Mixed practice</option><option value="rad">Degrees → radians</option><option value="deg">Radians → degrees</option><option value="sin">Exact sine</option><option value="cos">Exact cosine</option><option value="point">Unit-circle coordinates</option></select></label><label for="labels">Circle angle labels<select id="labels"><option value="both">Both degrees and radians</option><option value="deg">Degrees only</option><option value="rad">Radians only</option></select></label></div><p id="score" role="status"></p></section><div class="practice-layout"><section class="panel"><h2 id="question"></h2><div id="choices"></div><p id="feedback" role="status"></p><div class="button-row"><button id="next">Next question →</button><button id="reset">Reset score</button></div><p class="small">You can try again after an incorrect choice. Each correct answer earns one point; each submitted choice counts as one attempt.</p></section><section class="panel"><h2>Reference circle</h2><div id="circle"></div><p id="values" class="note" role="status"></p><p><a href="../demos/unit_circle.html">Open the full explorer</a></p></section></div><section class="panel"><h2>When you get stuck</h2><ol><li>Sketch the terminal ray. Is it on an axis or in a quadrant?</li><li>Find the acute angle to the horizontal axis.</li><li>Use the special triangle for the coordinate magnitudes.</li><li>Assign signs using left/right and above/below.</li></ol></section>'''
    page('practice/unit_circle_practice.html','Unit Circle Practice',b,'practice',{'kind':'practice','key':CONTRACT['practiceKey']})
def home():
    p=ROOT/'index.html';s=p.read_text();s=s.replace('Week 1 Notes: Angles, Radians, and the Unit Circle (PDF)','Module 1 Reading: Angles, Radians, and the Unit Circle').replace("m.week===1?['pdfs/PrecalcII_Week01.pdf'","m.week===1?['readings/module01_reading.html'")
    needle='${m.week===4&&j===1?'
    addition='${m.week===1&&j===0?`<br><a href="pdfs/PrecalcII_Week01.pdf" target="_blank" rel="noopener">Download Module 1 reading (PDF)</a>`:""}'
    if addition not in s:s=s.replace(needle,addition+needle)
    p.write_text(s)
if __name__=='__main__':
    reading();demos();activities();quiz();practice();home();print('Built seven Module 1 pages and updated the course reading link.')
